import React, { useEffect, useRef } from 'react';
import { ActivityIndicator, Image, Pressable, Text, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { Button, styles } from './ui';
import { PRODUCT_NAME } from '../lib/config';
import { colors, fonts, fs } from '../lib/theme';
import { useBiometric } from '../lib/biometric';

// Covers the signed-in UI after session restore. Sign-in and auth-callback are
// not a lock route, so OAuth and magic links still finish underneath.
export function BiometricLock() {
  const { locked, holding, method, busy, error, unlock, signInWithAccount } = useBiometric();
  const insets = useSafeAreaInsets();
  const unlockRef = useRef(unlock);
  unlockRef.current = unlock;

  useEffect(() => {
    if (!locked) return;
    let live = true;
    const timer = setTimeout(() => { if (live) void unlockRef.current(); }, 400);
    return () => { live = false; clearTimeout(timer); };
  }, [locked]);

  if (!locked && !holding) return null;

  return (
    <View
      accessibilityViewIsModal
      accessibilityLabel={locked ? 'App locked' : `Opening ${PRODUCT_NAME}`}
      style={{
        position: 'absolute', top: 0, left: 0, right: 0, bottom: 0, zIndex: 80,
        backgroundColor: colors.paper, alignItems: 'center', justifyContent: 'center',
        paddingTop: Math.max(insets.top, 24), paddingBottom: Math.max(insets.bottom, 24),
        paddingHorizontal: 28,
      }}
    >
      {holding ? <ActivityIndicator color={colors.navy} /> : (
        <View style={[styles.highlight, { width: '100%', maxWidth: 400, padding: 28 }]}>
          <View style={{ alignItems: 'center', marginBottom: 22 }}>
            <Image source={require('../assets/brand/logo.png')} style={{ width: 64, height: 64 }} resizeMode="contain" accessibilityLabel={PRODUCT_NAME} />
            <Text style={[styles.h1, { marginTop: 14 }]}>{PRODUCT_NAME}</Text>
            <Text style={[styles.muted, { marginTop: 6, textAlign: 'center' }]}>{method.detail}</Text>
          </View>
          <Button title={method.toggle} icon="lock-closed-outline" onPress={() => { void unlock(); }} loading={busy} />
          {error ? <Text style={{ color: colors.danger, fontFamily: fonts.sans, textAlign: 'center', marginTop: 12, fontSize: fs(14) }}>{error}</Text> : null}
          <Pressable onPress={() => { void signInWithAccount(); }} disabled={busy} accessibilityRole="button" style={{ marginTop: 18, alignSelf: 'center' }}>
            <Text style={[styles.link, { textAlign: 'center' }]}>Sign in with your account</Text>
          </Pressable>
          <Text style={[styles.muted, { textAlign: 'center', marginTop: 8, fontSize: fs(12) }]}>
            Google, Apple, or an email link. This signs out the session saved on this phone.
          </Text>
        </View>
      )}
    </View>
  );
}
