import React, { useEffect, useRef, useState } from 'react';
import { Stack, router, usePathname, useRootNavigationState, useSegments } from 'expo-router';
import { StatusBar } from 'expo-status-bar';
import { View, ActivityIndicator, Platform, Linking } from 'react-native';
import { SafeAreaProvider, useSafeAreaInsets } from 'react-native-safe-area-context';
import { useFonts, Newsreader_400Regular, Newsreader_600SemiBold } from '@expo-google-fonts/newsreader';
import { Inter_400Regular, Inter_500Medium, Inter_600SemiBold } from '@expo-google-fonts/inter';
import { SessionProvider, useSession } from '../lib/session';
import { BiometricProvider, useBiometric } from '../lib/biometric';
import { BiometricLock } from '../components/biometric-lock';
import { useTrackScreen } from '../lib/analytics';
import { useWebAnalytics } from '../lib/ga-web';
import { SIGNED_IN_HOME, peekExplicitLanding } from '../lib/auth';
import { correctedLanding, inAppPathFromUrl } from '../lib/landing';
import { usePushOpens } from '../lib/push';
import { PresenceProvider } from '../lib/presence';
import { DmAlertHost } from '../components/dm-alert';
import { PRODUCT_NAME } from '../lib/config';
import { colors, fonts, fs } from '../lib/theme';
import { DemoBanner } from '../components/ui';
import { FlashToast } from '../components/flash-toast';

function PushOpens() {
  const { userId, loading } = useSession();
  const nav = useRootNavigationState();
  usePushOpens(!loading && !!userId && !!nav?.key);
  return null;
}

const PENDING_LANDING = new Set(['/sign-in', '/auth-callback', '/preview']);

// Android can finish sign-in on Chat: the tab anchor is not loaded yet, a replace
// issued before the navigator exists is dropped, or a stale return path was read.
// Web keeps the URL the member actually opened.
function PostLoginHome() {
  const { userId, loading } = useSession();
  const pathname = usePathname();
  const segments = useSegments();
  const nav = useRootNavigationState();
  const decided = useRef(false);
  const [systemPath, setSystemPath] = useState<string | null | undefined>(undefined);

  useEffect(() => {
    if (Platform.OS === 'web') return;
    let live = true;
    // getInitialURL hangs on some Android launches when there is no URL. Don't wait forever.
    const timer = setTimeout(() => { if (live) setSystemPath((cur) => (cur === undefined ? null : cur)); }, 500);
    Linking.getInitialURL().then((url) => {
      if (live) setSystemPath(inAppPathFromUrl(url));
    }).catch(() => { if (live) setSystemPath(null); });
    return () => { live = false; clearTimeout(timer); };
  }, []);

  useEffect(() => {
    if (Platform.OS === 'web') return;
    if (decided.current || loading || !userId || !nav?.key || systemPath === undefined) return;
    if (!pathname || PENDING_LANDING.has(pathname)) return;
    const onTabsIndex = segments[0] === '(tabs)' && (pathname === '/' || pathname === '/index');
    if (pathname === '/' && !onTabsIndex) return;
    decided.current = true;
    const explicit = peekExplicitLanding();
    if (onTabsIndex) {
      router.replace(explicit ?? SIGNED_IN_HOME);
      return;
    }
    const next = correctedLanding(pathname, { systemPath, explicit, home: SIGNED_IN_HOME });
    if (next) router.replace(next);
  }, [loading, userId, pathname, segments, nav?.key, systemPath]);
  return null;
}

function TrackScreens() {
  const { userId, demo } = useSession();
  const { revealed } = useBiometric();
  const pathname = usePathname();
  useTrackScreen(pathname, !!userId && !demo && revealed);
  useWebAnalytics(pathname);
  return null;
}

function Shell() {
  const { demo } = useSession();
  // Android draws edge-to-edge (SDK 54+), so the status bar / camera cutout overlaps content.
  // Pad the whole app below the top inset on native; on web insets are 0.
  const insets = useSafeAreaInsets();
  const native = Platform.OS !== 'web';
  return (
    <View style={{ flex: 1, backgroundColor: colors.paper, paddingTop: native ? insets.top : 0, paddingLeft: native ? insets.left : 0, paddingRight: native ? insets.right : 0 }}>
      {demo ? <DemoBanner /> : null}
      {/* Nested provider re-measures from the padded frame, so native headers don't add the top inset twice. */}
      <SafeAreaProvider style={{ flex: 1 }}>
      <Stack screenOptions={{
        headerStyle: { backgroundColor: '#fff' }, headerShadowVisible: true, headerTintColor: colors.navy,
        headerTitleStyle: { fontFamily: fonts.sansBold, color: colors.navyDark, fontSize: fs(16) }, headerBackTitle: 'Back',
        contentStyle: { backgroundColor: colors.paper },
      }}>
        <Stack.Screen name="index" options={{ headerShown: false }} />
        {/* Web: signed-out /preview goes to sign-in; a signed-in visitor still sees the group home. Native: preview.tsx redirects home. */}
        <Stack.Screen name="preview" options={{ headerShown: false, title: PRODUCT_NAME }} />
        <Stack.Screen name="sign-in" options={{ headerShown: false }} />
        <Stack.Screen name="auth-callback" options={{ headerShown: false }} />
        <Stack.Screen name="(tabs)" options={{ headerShown: false }} />
        <Stack.Screen name="rooms/index" options={{ headerShown: false }} />
        <Stack.Screen name="rooms/[id]" options={{ title: 'Chat' }} />
        {/* Serif title in the page is the heading. The stack bar repeated it and left an empty band above. */}
        <Stack.Screen name="events/[id]" options={{ title: 'Event', headerShown: false }} />
        <Stack.Screen name="events/[id]/publish/[channel]" options={{ headerShown: false }} />
        <Stack.Screen name="e/[id]" options={{ title: 'Event' }} />
        <Stack.Screen name="events/manage/[id]" options={{ title: 'Event', headerShown: false }} />
        <Stack.Screen name="groups/[id]" options={{ title: 'Group', headerShown: false }} />
        <Stack.Screen name="groups/[id]/publish/[channel]" options={{ headerShown: false }} />
        <Stack.Screen name="g/[slug]" options={{ title: 'Group', headerShown: Platform.OS !== 'web' }} />
        <Stack.Screen name="groups/manage/[id]" options={{ title: 'Group', headerShown: false }} />
        <Stack.Screen name="meetup/[id]" options={{ title: 'Meetup event' }} />
        <Stack.Screen name="meetup/member/[id]" options={{ title: 'Member' }} />
        <Stack.Screen name="reports/[id]" options={{ title: 'Report' }} />
        <Stack.Screen name="profile" options={{ title: 'Profile' }} />
        <Stack.Screen name="guidelines" options={{ title: 'Guidelines' }} />
        <Stack.Screen name="socrates" options={{ title: 'Socrates' }} />
        <Stack.Screen name="mod" options={{ headerShown: false }} />
      </Stack>
      <FlashToast />
      </SafeAreaProvider>
      <DmAlertHost />
    </View>
  );
}

export default function RootLayout() {
  const [loaded] = useFonts({ Newsreader_400Regular, Newsreader_600SemiBold, Inter_400Regular, Inter_500Medium, Inter_600SemiBold });
  if (!loaded) return <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', backgroundColor: colors.paper }}><ActivityIndicator color={colors.navy} /></View>;
  return (
    <SafeAreaProvider>
    <SessionProvider>
      <BiometricProvider>
        <PushOpens />
        <PostLoginHome />
        <TrackScreens />
        <PresenceProvider>
          <StatusBar style="dark" />
          <Shell />
        </PresenceProvider>
        <BiometricLock />
      </BiometricProvider>
    </SessionProvider>
    </SafeAreaProvider>
  );
}
