import React, { useEffect, useState } from 'react';
import { Text, View } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { subscribeFlash } from '../lib/flash';
import { colors, fonts, fs } from '../lib/theme';

export function FlashToast() {
  const [message, setMessage] = useState<string | null>(null);
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout> | undefined;
    const unsubscribe = subscribeFlash((next) => {
      setMessage(next);
      if (timer) clearTimeout(timer);
      timer = setTimeout(() => setMessage(null), 3200);
    });
    return () => {
      unsubscribe();
      if (timer) clearTimeout(timer);
    };
  }, []);
  if (!message) return null;
  return (
    <View pointerEvents="none" accessibilityRole="alert" accessibilityLiveRegion="polite"
      style={{ position: 'absolute', left: 16, right: 16, bottom: 88, alignItems: 'center', zIndex: 20 }}>
      <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, backgroundColor: colors.navy, borderRadius: 8, paddingVertical: 12, paddingHorizontal: 16, maxWidth: 420 }}>
        <Ionicons name="checkmark-circle" size={18} color="#fff" />
        <Text style={{ color: '#fff', fontFamily: fonts.sansMedium, fontSize: fs(14) }}>{message}</Text>
      </View>
    </View>
  );
}
