/** Paths the tab navigator can open by itself. A specific return path or cold-start URL still wins. */
const ACCIDENTAL_HOMES = new Set(['/chat', '/me', '/rooms']);

export function normalizeInAppPath(path: string): string {
  let value = path.split('?')[0].split('#')[0].trim();
  if (!value.startsWith('/')) value = `/${value}`;
  if (value.length > 1 && value.endsWith('/')) value = value.slice(0, -1);
  if (value === '/app' || value.startsWith('/app/')) value = value.slice(4) || '/';
  return value || '/';
}

/**
 * Path from a native launch URL. Custom schemes use the host as the first segment
 * (`nycpprc://chat` is `/chat`), matching Expo Router. https URLs use the pathname,
 * with the `/app` base removed.
 */
export function inAppPathFromUrl(url: string | null | undefined): string | null {
  if (!url) return null;
  const raw = url.trim();
  if (!raw) return null;
  try {
    if (/^[a-z][a-z0-9+.-]*:/i.test(raw)) {
      const parsed = new URL(raw);
      const http = parsed.protocol === 'http:' || parsed.protocol === 'https:';
      const path = http ? parsed.pathname : `${parsed.hostname}${parsed.pathname}`;
      return normalizeInAppPath(path);
    }
  } catch { /* treat as a raw path */ }
  return normalizeInAppPath(raw);
}

/**
 * Where to send someone who landed on Chat, Profile, or the legacy Rooms redirect
 * with no specific destination. Returns null when the current path should stay.
 */
export function correctedLanding(pathname: string, opts: { systemPath: string | null; explicit: string | null; home: string }): string | null {
  const path = normalizeInAppPath(pathname);
  if (!ACCIDENTAL_HOMES.has(path)) return null;
  if (opts.explicit && normalizeInAppPath(opts.explicit) === path) return null;
  if (opts.systemPath && normalizeInAppPath(opts.systemPath) === path) return null;
  return opts.home;
}
